    "<code class=\"mono\" style=\"font-size:15px;user-select:all;cursor:pointer\" title=\"点一下整条选中\">{0}</code>": "<code class=\"mono\" style=\"font-size:15px;user-select:all;cursor:pointer\" title=\"Click to select the whole line\">{0}</code>",
