    "<h2 style=\"margin-top:16px\">问话记录</h2>\n      <table><tr><th>问了什么</th><th>状态</th><th>为什么</th></tr>{0}</table>": "<h2 style=\"margin-top:16px\">Query Log</h2>\n      <table><tr><th>Asked</th><th>Status</th><th>Why</th></tr>{0}</table>",
    "<option value=\"\">所有网卡（含回环）</option>": "<option value=\"\">All adapters (including loopback)</option>",
    "<option value=\"\">（对端没列出口 —— 要自己确认那台上的口名）</option>": "<option value=\"\">(the peer listed no ports — confirm the port names on that device yourself)</option>",
    "<option value=\"\">（还没有登记的设备）</option>": "<option value=\"\">(no registered devices yet)</option>",
